package ir.orix.school.assessment.domain;
import jakarta.persistence.*; import ir.orix.school.organization.domain.Tenant; import ir.orix.school.shared.persistence.AuditedEntity;
@Entity @Table(name="assessment_section",schema="school")
public class AssessmentSection extends AuditedEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_id") private Assessment assessment; @Column(nullable=false,length=200) private String title; @Column(columnDefinition="TEXT") private String instructions; @Column(name="sequence_number",nullable=false) private int sequenceNumber; protected AssessmentSection(){} public AssessmentSection(Tenant tenant,Assessment assessment,String title,String instructions,int sequence){this.tenant=tenant;this.assessment=assessment;this.title=title.strip();this.instructions=instructions==null||instructions.isBlank()?null:instructions.strip();this.sequenceNumber=sequence;} public Assessment getAssessment(){return assessment;} public String getTitle(){return title;} public String getInstructions(){return instructions;} public int getSequenceNumber(){return sequenceNumber;} }
